insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('b946ec25-e6fb-434c-a36d-ff3d5c663d67', 'N5', 'どう、どんな、どれ', 'Thế nào? (どう) ／ Như thế nào? (どんな+N) ／ Cái nào? (どれ)', 'どう hỏi cảm nhận chung; どんな+N hỏi tính chất của N; どれ hỏi chọn 1 trong nhiều vật', NULL, NULL, NULL, NULL, NULL, '{}', NULL, 38, 'どう、どんな、どれ', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('606dacc4-e1ff-4c1a-a5ac-1ee01f657e01', 'N5', 'Vる（Thể từ điển／Thể ngắn）', 'Thể từ điển (thể ngắn/thể nguyên dạng) của động từ', 'Nhóm I: ～います→～う; Nhóm II: ～えます/～います→～る; Nhóm III: します→する, きます→くる', 'V ます → V る: Nhóm I います→う (食べいます sai, ví dụ 食べます→食べる cho Nhóm II); Nhóm III します→する, きます→くる', 'Dạng gốc/từ điển của động từ, dùng làm nền cho nhiều mẫu ngữ pháp khác (ことができます, まえに, など)', 'thông thường (không lịch sự)', NULL, NULL, '{}', NULL, 38, 'Vる（Thể từ điển／Thể ngắn）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('a07d0ca6-c835-4eec-b41d-4801dac499e0', 'N5', 'N が + Động từ／Tính từ（わかります・好きです）', 'Biết/hiểu N (わかります), có N/đồ vật (あります), thích/ghét/giỏi/kém N (好きです/嫌いです/上手です/下手です)', 'Nhóm động từ/tính từ đặc biệt này luôn dùng trợ từ が cho đối tượng, không dùng を', 'N + が + わかります／あります／好きです／嫌いです／上手です／下手です', 'Diễn tả khả năng hiểu biết, sự tồn tại, hoặc cảm xúc/đánh giá về 1 đối tượng — đối tượng luôn đi với が', NULL, NULL, 'Rất hay nhầm dùng を thay vì が với nhóm động từ/tính từ này (日本語をわかります ✗ → 日本語がわかります ✓).', '{}', NULL, 38, 'N が + Động từ／Tính từ（わかります・好きです）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f1e41b32-3133-4eaa-8be7-9e83aa176d1e', 'N5', 'どんな N が ...か', 'Bạn thích N như thế nào?', 'どんな+N+が+好きですか = hỏi loại/kiểu N nào được thích', 'どんな + N + が + Động từ/Tính từ (好きです...) + か', 'Hỏi cụ thể loại/kiểu của N mà người nghe thích/quan tâm', NULL, NULL, NULL, '{"どう、どんな、どれ"}', NULL, 38, 'どんな N が ...か', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5d61ee1a-401e-4e52-9f62-baa5b0ec5346', 'N5', 'よく・だいたい・たくさん・すこし・あまり・ぜんぜん', 'Cách nói mức độ/số lượng: rất/hay, đại khái, nhiều, một ít, không...lắm, hoàn toàn không', 'あまり/ぜんぜん bắt buộc đi với thể phủ định', 'よく／だいたい／たくさん／すこし + V(bất kỳ) ； あまり／ぜんぜん + V(thể phủ định)', 'Trạng từ chỉ mức độ hoặc tần suất, bổ nghĩa cho động từ', NULL, 'あまり + phủ định = không...lắm; ぜんぜん + phủ định = hoàn toàn không.', 'あまり/ぜんぜん PHẢI đi với thể phủ định của động từ, không dùng với thể khẳng định.', '{}', NULL, 38, 'よく・だいたい・たくさん・すこし・あまり・ぜんぜん', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8956534e-1627-4178-ad63-c7f13c6efc00', 'N5', 'S1 から、S2', 'Vì S1, nên S2', 'から đặt sau lý do (S1), trước kết quả (S2)', 'S1(lý do) + から、+ S2(kết quả)', 'Nêu lý do (S1) dẫn đến kết quả/hành động (S2)', NULL, NULL, NULL, '{"どうして+ ～か。→ ～から"}', NULL, 38, 'S1 から、S2', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7a077168-e367-4612-95e9-502ab3022ace', 'N5', 'どうして + ～か。→ ～から', 'Tại sao ...? → Vì ...', 'どうして hỏi lý do, trả lời kết thúc bằng から', 'どうして + V(thể ます) + か。→ S(lý do) + から。', 'Hỏi lý do của 1 việc, trả lời bằng cách nêu lý do kết thúc bằng から', NULL, NULL, NULL, '{"S1 から、S2"}', NULL, 38, 'どうして + ～か。→ ～から', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7a3f745a-6c13-48e7-be82-d24ff6b228e0', 'N5', 'N1 の N2（vị trí）', 'Ở (địa điểm) có ai／có cái gì', 'N1 = vị trí (trên/dưới/trong...), N2 = vật/người', '(địa điểm)の上／下／中／隣 + に + N(người/vật) + が + います／あります', 'Hỏi/trả lời có ai hoặc có cái gì ở 1 vị trí cụ thể', NULL, 'Bổ sung: hỏi có bạn gái/trai chưa cũng dùng cấu trúc います/いません tương tự (彼女がいますか。).', NULL, '{}', NULL, 39, 'N1 の N2（vị trí）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('dc8c107a-bfb5-471a-b0cb-f1c5d3e9c1bb', 'N5', '（Người／con vật／đồ vật）は どこに + います／あります', 'Ai／cái gì／con gì ở đâu', 'Chủ ngữ trước は, địa điểm sau どこに', '(Người/con vật/đồ vật) + は + どこに + いますか／ありますか', 'Hỏi/trả lời vị trí của 1 người/vật/con vật đã biết', NULL, NULL, NULL, '{"N1 の N2（vị trí）"}', NULL, 39, '（Người／con vật／đồ vật）は どこに + います／あります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7a875aa9-5e3c-457c-b45f-25469247b6fb', 'N5', '～や～など', 'Mẫu câu liệt kê: nào là ~ nào là ~ (liệt kê không đầy đủ)', 'や liệt kê vài ví dụ tiêu biểu, など = vân vân', 'N1 + や + N2 + など', 'Liệt kê một vài ví dụ tiêu biểu trong số nhiều thứ, không liệt kê hết', NULL, 'Khác と (liệt kê đầy đủ, hết mọi thứ) — や chỉ nêu vài ví dụ tiêu biểu.', NULL, '{}', NULL, 39, '～や～など', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('902a3692-e069-4804-95c1-e72325ff7b57', 'b946ec25-e6fb-434c-a36d-ff3d5c663d67', 1, 'どう: N1 thế nào? (nhận xét/cảm nhận chung)', 'N1 は どうですか。', 'Hỏi cảm nhận/đánh giá chung về 1 người/vật/việc', NULL, 38, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('fdbd0515-1871-4c77-9bc5-60563c78bdfe', 'b946ec25-e6fb-434c-a36d-ff3d5c663d67', 2, 'どんな+N: N1 là N2 như thế nào?', 'N1 は どんな N2 ですか。', 'Hỏi tính chất/đặc điểm cụ thể của N1 thông qua loại N2', NULL, 38, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('96a1639a-800d-4c94-a0e0-580a4532d3d5', 'b946ec25-e6fb-434c-a36d-ff3d5c663d67', 3, 'どれ: N1 là cái nào? (chọn giữa nhiều vật)', 'N1 は どれ ですか。', 'Hỏi chọn ra 1 vật cụ thể trong số nhiều vật đã biết', NULL, 38, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('a85373fb-294c-4046-997f-d040c8fd95ec', '7a3f745a-6c13-48e7-be82-d24ff6b228e0', 1, 'Ở (địa điểm) có ai (người/động vật)', '(địa điểm) + に + だれ + が + いますか', 'Hỏi/trả lời sự hiện diện của người/động vật ở 1 nơi', NULL, 39, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('31c3dbb5-7ad9-4ef1-9b8f-07403c1b2020', '7a3f745a-6c13-48e7-be82-d24ff6b228e0', 2, 'Ở (địa điểm) có cái gì (đồ vật)', '(địa điểm) + に + 何 + が + ありますか', 'Hỏi/trả lời sự tồn tại của đồ vật ở 1 nơi', NULL, 39, 'pdf');
