insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('a07d0ca6-c835-4eec-b41d-4801dac499e0', NULL, 1, 'standard', '私は日本語がわかります。', 'Tôi hiểu tiếng Nhật.', '私は日本語＿＿＿わかります。', 'が', 'pdf');
