insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('f1e41b32-3133-4eaa-8be7-9e83aa176d1e', NULL, 3, 'daily', 'どんな映画が好きですか。', 'Bạn thích loại phim như thế nào?', '＿＿＿映画が好きですか。', 'どんな', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5d61ee1a-401e-4e52-9f62-baa5b0ec5346', NULL, 1, 'standard', '日本語がよく分かります。', 'Tôi hiểu rõ tiếng Nhật.', '日本語が＿＿＿分かります。', 'よく', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5d61ee1a-401e-4e52-9f62-baa5b0ec5346', NULL, 2, 'standard', 'ビールをたくさん飲みました。', 'Tôi đã uống rất nhiều bia.', 'ビールを＿＿＿飲みました。', 'たくさん', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5d61ee1a-401e-4e52-9f62-baa5b0ec5346', NULL, 3, 'standard', 'ビールをぜんぜん飲みませんでした。', 'Tôi hoàn toàn không uống bia.', 'ビールを＿＿＿飲みませんでした。', 'ぜんぜん', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8956534e-1627-4178-ad63-c7f13c6efc00', NULL, 1, 'standard', 'お金があまりありませんから、カメラを買いません。', 'Vì không có tiền cho lắm nên tôi không mua máy ảnh.', 'お金があまりありません＿＿＿、カメラを買いません。', 'から', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8956534e-1627-4178-ad63-c7f13c6efc00', NULL, 2, 'standard', '時間がありませんから、サッカーをしません。', 'Vì không có thời gian nên tôi không chơi đá bóng.', '時間がありません＿＿＿、サッカーをしません。', 'から', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8956534e-1627-4178-ad63-c7f13c6efc00', NULL, 3, 'daily', 'あついですから、まどをあけます。', 'Vì nóng nên tôi mở cửa sổ.', 'あついです＿＿＿、まどをあけます。', 'から', 'generated');
